"""Fuzz with denser manifests: many segments, high low_count, mixed rows."""
import json, random, subprocess, os, sys, ipaddress
sys.path.insert(0,'/workspace/tmp/t')
import ref
CAND=['python3','/workspace/submission/ipv6_replay.py']
W='/workspace/tmp/t/work'
os.makedirs(W, exist_ok=True)

def gen(rng):
    low = rng.randint(1, 32)
    att = rng.randint(1, 3)
    wins = []
    used_global = 0
    nwid = 0
    for wi in range(rng.randint(1, 4)):
        scopes = []
        nets = set()
        nsc = rng.randint(1, 3)
        for si in range(nsc):
            if used_global + 8 > 2048: break
            if rng.random() < 0.5:
                plen, base = 56, int(ipaddress.IPv6Network('2001:db8:%x:%x00::/56' % (rng.randrange(1,65535), rng.randrange(0,256))).network_address)
                subs = sorted(rng.sample(range(256), rng.randint(1, 8)))
                new = {base + (s << 64) for s in subs}
            else:
                plen, base = 64, int(ipaddress.IPv6Network('2001:db8:%x:%x::/64' % (rng.randrange(1,65535), rng.randrange(0,65536))).network_address)
                subs = [0]; new = {base}
            if new & nets: continue
            nets |= new; used_global += len(new)
            scopes.append({'id': 'sc%d' % si, 'prefix': str(ipaddress.IPv6Address(base)) + ('/%d' % plen), 'subnets': subs})
        if not scopes: continue
        nwid += 1
        wins.append({'id': 'w%d' % wi, 'start_ms': rng.choice([0, 10**12, rng.randint(0,10**12)]),
                     'scopes': scopes})
    return {'version':1,'seed':rng.randint(0,2**64-1),'low_count':low,'attempts':att,
            'spacing_ms':rng.randint(1,1000),'timeout_ms':rng.randint(1,1000000),'windows':wins}

def rows(rng, plan, m):
    out = []
    for _ in range(rng.randint(0, 150)):
        p = rng.choice(plan['probes'])
        d = {'probe_id': p['id'], 'received_ms': rng.randint(p['sent_ms']-1, p['deadline_ms']+1),
             'target': p['target'], 'source': p['target'], 'type': 129, 'code': 0}
        r = rng.random()
        if r < 0.45: ty, co = 129, 0
        elif r < 0.85: ty, co = 1, rng.randint(0, 6)
        else: ty, co = rng.choice([(129,1),(1,7),(2,0)])
        d['type'], d['code'] = ty, co
        if rng.random() < 0.35:
            base = int(ipaddress.IPv6Address(p['target'])) & ~((1<<64)-1)
            d['source'] = str(ipaddress.IPv6Address(base | rng.getrandbits(64)))
        if rng.random() < 0.1:
            d['source'] = str(ipaddress.IPv6Address(int(ipaddress.IPv6Network('2001:db8::/32').network_address) + rng.getrandbits(112)))
        items = list(d.items()); rng.shuffle(items)
        out.append(json.dumps(dict(items)))
    rng.shuffle(out)
    return out

bad = 0
N = int(sys.argv[1]) if len(sys.argv)>1 else 50
for it in range(N):
    rng = random.Random(700000+it)
    m = gen(rng)
    plan = ref.ref_plan(m)[0]
    rs = rows(rng, plan, m)
    mp = os.path.join(W,'bf.json'); rp = os.path.join(W,'bf.jsonl')
    open(mp,'w').write(json.dumps(m)); open(rp,'w').write('\n'.join(rs)+'\n')
    g = subprocess.run(CAND+['replay',mp,rp],capture_output=True)
    if g.returncode:
        print('FAIL', it, g.returncode, g.stderr[:200]); bad+=1; continue
    exp = ref.ref_replay(m, [r.encode() for r in rs])
    got = json.loads(g.stdout)
    if got != exp:
        print('MISMATCH', it); bad += 1
        for k in exp:
            if got.get(k) != exp[k]:
                print(' key', k)
                a, b = got.get(k), exp[k]
                if k == 'segments':
                    for x, y in zip(a, b):
                        if x != y:
                            for kk in y:
                                if x.get(kk) != y[kk]:
                                    print('   field', kk); print('    got', json.dumps(x.get(kk))[:300]); print('    exp', json.dumps(y[kk])[:300])
                            break
                else:
                    print('  got', json.dumps(a)[:200]); print('  exp', json.dumps(b)[:200])
        if bad > 2: break
print('bigfuzz bad =', bad)
